"""Emoji shortcode resolution.

Maps :shortcode: names to Unicode characters. Data sourced from:
- GitHub emoji API (https://api.github.com/emojis)
- iamcal/emoji-data (Slack's base set)
- Unicode CLDR short names (via Emojibase)
- Emojibase community shortcodes

Merge order: _COMMON | _CLDR | _EMOJIBASE | _GITHUB | _SLACK (Slack wins conflicts).
"""

from __future__ import annotations

from collections.abc import Mapping
from types import MappingProxyType


